/** Private file storage. Paths are generated by services, never by clients. */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(process.env.STORAGE_ROOT || path.join(__dirname, '..', '..', 'storage'));

function badPath() {
  return Object.assign(new Error('Invalid storage path.'), { code: 'BAD_PATH', status: 400 });
}

function segments(value, allowEmpty = false) {
  if (typeof value !== 'string' || (!value && !allowEmpty) || path.isAbsolute(value) || value.includes('\\')) throw badPath();
  if (!value && allowEmpty) return [];
  const parts = value.split('/');
  if (parts.some(part => !part || part === '.' || part === '..' || /[\x00-\x1f\x7f<>:"|?*]/.test(part) || /[. ]$/.test(part))) throw badPath();
  return parts;
}

function filename(value) {
  if (segments(value).length !== 1) throw badPath();
  return value;
}

function createStore(rootPath) {
  const root = path.resolve(rootPath);
  function resolveInside(folder, name) {
    const parts = segments(folder, true);
    if (name !== undefined && name !== '') parts.push(filename(name));
    return path.join(root, ...parts);
  }

  // A symlink inside a storage tree must never redirect a request elsewhere.
  function assertDirectorySync(folder = '') {
    const parts = segments(folder, true);
    let current = root;
    for (const part of [null, ...parts]) {
      if (part !== null) current = path.join(current, part);
      const stat = fs.lstatSync(current);
      if (!stat.isDirectory() || stat.isSymbolicLink()) throw badPath();
    }
    return current;
  }

  async function ensureDirectory(folder = '') {
    const parts = segments(folder, true);
    const createdRoot = await fs.promises.mkdir(root, { recursive: true, mode: 0o750 });
    let current = root;
    let stat = await fs.promises.lstat(current);
    if (!stat.isDirectory() || stat.isSymbolicLink()) throw badPath();
    if (createdRoot) {
      let created = root;
      while (created === createdRoot || created.startsWith(createdRoot + path.sep)) {
        await syncDirectory(path.dirname(created));
        if (created === createdRoot) break;
        created = path.dirname(created);
      }
    }
    for (const part of parts) {
      const parent = current;
      current = path.join(current, part);
      let created = true;
      await fs.promises.mkdir(current, { mode: 0o750 }).catch(error => {
        if (error.code !== 'EEXIST') throw error;
        created = false;
      });
      stat = await fs.promises.lstat(current);
      if (!stat.isDirectory() || stat.isSymbolicLink()) throw badPath();
      if (created) await syncDirectory(parent);
    }
    return current;
  }

  async function syncDirectory(dir) {
    let handle;
    try {
      handle = await fs.promises.open(dir, fs.constants.O_RDONLY);
      await handle.sync();
    } catch (error) {
      // Windows cannot fsync directory handles. Linux deployments do so.
      if (process.platform !== 'win32' || !['EINVAL', 'EPERM', 'EISDIR', 'ENOTSUP'].includes(error.code)) throw error;
    } finally { await handle?.close(); }
  }

  async function write(folder, name, buffer) {
    filename(name);
    const dir = await ensureDirectory(folder);
    const destination = resolveInside(folder, name);
    const temporary = path.join(dir, `.upload-${crypto.randomUUID()}`);
    let handle;
    let published = false;
    try {
      handle = await fs.promises.open(temporary, 'wx', 0o640);
      await handle.writeFile(buffer);
      await handle.sync();
      await handle.close();
      handle = null;
      assertDirectorySync(folder);
      await fs.promises.link(temporary, destination); // Atomic, never replaces another file.
      published = true;
      await syncDirectory(dir);
      return { path: destination, size: buffer.length };
    } catch (error) {
      if (published) await fs.promises.unlink(destination).catch(() => {});
      throw error;
    } finally {
      await handle?.close();
      await fs.promises.unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; });
    }
  }

  /** Publish a streamed upload only after every byte and fsync completes. */
  async function writeStream(folder, name, source) {
    filename(name);
    const dir = await ensureDirectory(folder);
    const destination = resolveInside(folder, name);
    const temporary = path.join(dir, `.upload-${crypto.randomUUID()}`);
    let handle, published = false;
    try {
      handle = await fs.promises.open(temporary, 'wx', 0o640);
      // FileHandle stream close semantics differ across Node versions. Keep
      // ownership of the descriptor explicit and honor backpressure per chunk.
      let position = 0;
      for await (const chunk of source) {
        let offset = 0;
        while (offset < chunk.length) {
          const { bytesWritten } = await handle.write(chunk, offset, chunk.length - offset, position);
          if (!bytesWritten) throw new Error('Storage write made no progress.');
          offset += bytesWritten;
          position += bytesWritten;
        }
      }
      await handle.sync(); await handle.close(); handle = null;
      assertDirectorySync(folder);
      await fs.promises.link(temporary, destination); published = true;
      await syncDirectory(dir);
      return { path: destination };
    } catch (error) {
      if (published) await fs.promises.unlink(destination).catch(() => {});
      throw error;
    } finally {
      await handle?.close();
      await fs.promises.unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; });
    }
  }

  function openSync(folder, name) {
    assertDirectorySync(folder);
    const file = resolveInside(folder, filename(name));
    const before = fs.lstatSync(file);
    if (!before.isFile() || before.isSymbolicLink()) throw badPath();
    const descriptor = fs.openSync(file, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW || 0));
    try {
      const opened = fs.fstatSync(descriptor);
      if (!opened.isFile() || opened.dev !== before.dev || opened.ino !== before.ino) throw badPath();
      return fs.createReadStream(null, { fd: descriptor, autoClose: true });
    } catch (error) { fs.closeSync(descriptor); throw error; }
  }

  async function open(folder, name) {
    assertDirectorySync(folder);
    const file = resolveInside(folder, filename(name));
    const before = await fs.promises.lstat(file);
    if (!before.isFile() || before.isSymbolicLink()) throw badPath();
    const handle = await fs.promises.open(file, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW || 0));
    try {
      const stat = await handle.stat();
      if (!stat.isFile() || stat.dev !== before.dev || stat.ino !== before.ino) throw badPath();
      return { stream: handle.createReadStream(), size: stat.size };
    } catch (error) { await handle.close(); throw error; }
  }

  async function read(folder, name) {
    const { stream } = await open(folder, name);
    const chunks = [];
    for await (const chunk of stream) chunks.push(chunk);
    return Buffer.concat(chunks);
  }

  async function remove(folder, name) {
    const file = resolveInside(folder, name);
    try {
      assertDirectorySync(folder);
      const stat = await fs.promises.lstat(file);
      if (!stat.isFile() || stat.isSymbolicLink()) throw badPath();
      await fs.promises.unlink(file);
    } catch (error) { if (error.code !== 'ENOENT') throw error; }
  }

  return { ROOT: root, resolveInside, assertDirectorySync, ensureDirectory, write, writeStream, open, openSync, read, remove };
}

module.exports = { ...createStore(ROOT), createStore };
